import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r', encoding='utf-8') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze the policies to determine the authoritative one
if len(policies) >= 2:
    print("\nAnalyzing policies to determine authoritative version:")

    # Check for version numbers or timestamps
    for filename, policy in policies.items():
        print(f"\n{filename}:")
        if 'version' in policy:
            print(f"  Version: {policy['version']}")
        if 'effective_date' in policy:
            print(f"  Effective Date: {policy['effective_date']}")
        if 'last_updated' in policy:
            print(f"  Last Updated: {policy['last_updated']}")
        if 'is_authoritative' in policy:
            print(f"  Authoritative flag: {policy['is_authoritative']}")

    # Determine authoritative policy based on criteria
    authoritative_policy = None
    authoritative_reason = ""

    # First check for explicit authoritative flag
    for filename, policy in policies.items():
        if policy.get('is_authoritative') == True:
            authoritative_policy = filename
            authoritative_reason = "Explicit authoritative flag set to True"
            break

    # If no explicit flag, check for highest version
    if not authoritative_policy:
        max_version = None
        for filename, policy in policies.items():
            if 'version' in policy:
                try:
                    version = float(policy['version'])
                    if max_version is None or version > max_version[0]:
                        max_version = (version, filename)
                except:
                    pass

        if max_version:
            authoritative_policy = max_version[1]
            authoritative_reason = f"Highest version number: {max_version[0]}"

    # If still not determined, check for most recent date
    if not authoritative_policy:
        latest_date = None
        for filename, policy in policies.items():
            date_fields = ['effective_date', 'last_updated', 'date']
            for field in date_fields:
                if field in policy:
                    date_str = policy[field]
                    if latest_date is None or date_str > latest_date[0]:
                        latest_date = (date_str, filename)

        if latest_date:
            authoritative_policy = latest_date[1]
            authoritative_reason = f"Most recent date: {latest_date[0]}"

    # If still not determined, use the first one as default
    if not authoritative_policy and policies:
        authoritative_policy = list(policies.keys())[0]
        authoritative_reason = "First available policy (no other criteria met)"

    print(f"\nAuthoritative policy determined: {authoritative_policy}")
    print(f"Reason: {authoritative_reason}")

    # Store the authoritative policy information
    authoritative_info = {
        'authoritative_policy': authoritative_policy,
        'reason': authoritative_reason,
        'all_policies': list(policies.keys())
    }

    print(f"\nAuthoritative policy details: {authoritative_info}")

elif len(policies) == 1:
    print(f"\nOnly one policy found: {list(policies.keys())[0]}")
    print("This is automatically the authoritative policy.")
else:
    print("\nNo policy documents found or could not be loaded.")
